from fractions import Fraction

def get_neighbors(r):
    neighbors = []
    # r' = -r
    r_s = -r
    if r_s != r:
        neighbors.append(r_s)
    # r' = 1-r
    r_t = 1 - r
    if r_t != r:
        neighbors.append(r_t)
    # r' = 1/r
    if r != 0:
        r_u = 1/r
        if r_u != r:
            neighbors.append(r_u)
    return neighbors

def find_component_coloring(start_node, start_val):
    visited = {start_node: start_val}
    queue = [start_node]
    while queue:
        curr = queue.pop(0)
        val = visited[curr]
        for neighbor in get_neighbors(curr):
            if neighbor not in visited:
                visited[neighbor] = 1 - val
                queue.append(neighbor)
            else:
                if visited[neighbor] == val:
                    return None # Not bipartite
    return visited

