def dist_to_target(start, target):
    if start == target:
        return 0
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        curr, d = queue.popleft()
        for neighbor in get_neighbors(curr):
            if neighbor == target:
                return d + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, d + 1))
    return None

